"use strict";(self.webpackChunkrodriguesfas_github_io=self.webpackChunkrodriguesfas_github_io||[]).push([[8319],{2302:e=>{e.exports=JSON.parse('{"label":"Startups","permalink":"/docs/tags/startups","allTagsPath":"/docs/tags","count":5,"items":[{"id":"Startups/cowatch","title":"CoWatch","description":"Sou co-fundador da CoWatch, uma startup que visa revolucionar a gest\xe3o de rebanhos com tecnologia de ponta. A plataforma permite monitorar a alimenta\xe7\xe3o de cada animal com precis\xe3o, otimizando a produ\xe7\xe3o e maximizando os lucros. Oferecemos: Monitoramento em tempo real, An\xe1lises avan\xe7adas, Integra\xe7\xe3o com diversas ferramentas, Protocolos de seguran\xe7a robustos.","permalink":"/docs/Startups/cowatch"},{"id":"Startups/createlab","title":"CreateLab","description":"Fui co-fundador da CreateLab, uma startup voltada para educa\xe7\xe3o tecnol\xf3gica. A empresa tinha como foco o desenvolvimento de material did\xe1tico para o ensino de rob\xf3tica educacional destinado a crian\xe7as e adolescentes, al\xe9m de oferecer capacita\xe7\xe3o para professores nessa \xe1rea.","permalink":"/docs/Startups/createlab"},{"id":"Startups/immonex","title":"ImmoNex","description":"Sou co-fundador do ImmoNex, um servi\xe7o crido em 25/10/2023 dedicado para o mercado imobili\xe1rio, oferecendo solu\xe7\xf5es para a gest\xe3o de im\xf3veis e propriedades. A startup se destaca por fornecer ferramentas que facilitam o gerenciamento de vendas, loca\xe7\xf5es e administra\xe7\xe3o de im\xf3veis, visando otimizar processos e melhorar a experi\xeancia tanto para corretores quanto para clientes.","permalink":"/docs/Startups/immonex"},{"id":"Startups/yaakov","title":"Yaakov","description":"Sou co-fundador da Software House Yaakov, uma empresa especializada em solu\xe7\xf5es de tecnologia e desenvolvimento de software. Na Yaakov, lidero o desenvolvimento de aplicativos, websites e sistemas personalizados para clientes de diversos setores. Minha atua\xe7\xe3o abrange todas as fases do ciclo de desenvolvimento, desde a an\xe1lise de requisitos at\xe9 a implanta\xe7\xe3o e manuten\xe7\xe3o. Colaboro ativamente com a equipe para projetar e implementar solu\xe7\xf5es inovadoras que atendem \xe0s necessidades de neg\xf3cios dos nossos clientes. Al\xe9m disso, participo da defini\xe7\xe3o da estrat\xe9gia e dire\xe7\xe3o da empresa como membro da equipe de lideran\xe7a, contribuindo para o crescimento e sucesso da Yaakov.","permalink":"/docs/Startups/yaakov"},{"id":"Startups/zafie","title":"Zafie","description":"Em 06/2021 co-fundei o Zafie, um gestor de pedidos online completo, projetado para otimizar as opera\xe7\xf5es e aumentar as vendas de empresas de Food e varejo em geral. Com recursos como card\xe1pio digital, QRCode de mesa, integra\xe7\xf5es com WhatsApp, PDV, e muito mais, a Zafie simplifica a administra\xe7\xe3o de pedidos e melhora a experi\xeancia do cliente. Al\xe9m disso, oferece ferramentas para promo\xe7\xf5es, cupons de desconto e cashback.","permalink":"/docs/Startups/zafie"}]}')}}]);